function recordWithData(record) {
  const data = record?.data && typeof record.data === "object" ? record.data : {};
  return { ...data, ...record, data };
}

function deriveDemoAccess(role) {
  const groups = demoRoleGroups[role] || [];
  const allowed = (table, action) => fullAccessRoles.has(role) || permissions[table][action].some((group) => groups.includes(group));
  const build = (action) => Object.fromEntries(Object.keys(permissions).map((table) => [table, allowed(table, action)]));
  return { canRead: build("read"), canCreate: build("create"), canUpdate: build("update"), canArchive: build("archive") };
}

function useHealthcareCollection(table, seed, { isLive, canRead }, currentUser, onToast) {
  const utils = trpc.useUtils();
  const [demoRows, setDemoRows] = useState(() => seed.map(recordWithData));
  const input = useMemo(() => ({ table, limit: 250, includeArchived: false }), [table]);
  const query = trpc.healthcare.list.useQuery(input, { enabled: Boolean(isLive && canRead), retry: false, staleTime: 15_000 });
  const createMutation = trpc.healthcare.create.useMutation();
  const updateMutation = trpc.healthcare.update.useMutation();
  const archiveMutation = trpc.healthcare.archive.useMutation();
  const access = isLive ? query.data?.access : deriveDemoAccess(currentUser?.role || "Super Administrator");

  const rows = isLive ? (query.data?.records || []).map(recordWithData) : demoRows;
  const refresh = async () => {
    if (isLive && canRead) await utils.healthcare.list.invalidate(input);
  };
  const create = async (record) => {
    if (!isLive) {
      const created = recordWithData({ ...record, id: `demo-${table}-${Date.now()}`, created_at: new Date().toISOString() });
      setDemoRows((current) => [created, ...current]);
      onToast?.("Record saved in demo workspace", "success");
      return created;
    }
    const result = await createMutation.mutateAsync({ table, record });
    await refresh();
    onToast?.("Healthcare record saved", "success");
    return recordWithData(result.record);
  };
  const update = async (id, patch) => {
    if (!isLive) {
      setDemoRows((current) => current.map((row) => row.id === id ? recordWithData({ ...row, ...patch, data: { ...row.data, ...(patch.data || {}) } }) : row));
      onToast?.("Record updated in demo workspace", "success");
      return;
    }
    await updateMutation.mutateAsync({ table, id, patch });
    await refresh();
    onToast?.("Healthcare record updated", "success");
  };
  const archive = async (id) => {
    if (!isLive) {
      setDemoRows((current) => current.filter((row) => row.id !== id));
      onToast?.("Record archived in demo workspace", "success");
      return;
    }
    await archiveMutation.mutateAsync({ table, id });
    await refresh();
    onToast?.("Healthcare record archived", "success");
  };
  return { table, rows, loading: Boolean(isLive && canRead && query.isLoading), error: query.error?.message || null, access, refreshing: query.isFetching && !query.isLoading, create, update, archive, busy: createMutation.isPending || updateMutation.isPending || archiveMutation.isPending, refresh };
}

function fmtDate(value, options = { day: "2-digit", month: "short", year: "numeric" }) {
  if (!value) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "—" : new Intl.DateTimeFormat("en-TZ", options).format(date);
}

function fmtMoney(value, currency = "TZS") {
  return new Intl.NumberFormat("en-TZ", { style: "currency", currency, maximumFractionDigits: 0 }).format(Number(value || 0));
}

function compactDateTime(value) {
  return fmtDate(value, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" });
}

function calculateAge(dateOfBirth) {
  if (!dateOfBirth) return "—";
  const birth = new Date(dateOfBirth);
  const today = new Date();
  let age = today.getFullYear() - birth.getFullYear();
  if (today < new Date(today.getFullYear(), birth.getMonth(), birth.getDate())) age -= 1;
  return Number.isFinite(age) && age >= 0 ? `${age} yrs` : "—";
}

function statusStyle(status = "") {
  const value = String(status).toLocaleLowerCase();
  if (/(priority|urgent|overdue|unpaid|cancelled)/.test(value)) return "bg-rose-50 text-rose-700 ring-rose-200";
  if (/(confirmed|active|paid|signed|recorded|dispensed|resulted|completed)/.test(value)) return "bg-emerald-50 text-emerald-700 ring-emerald-200";
  if (/(progress|checked|awaiting|ordered|pending)/.test(value)) return "bg-amber-50 text-amber-700 ring-amber-200";
  return "bg-slate-100 text-slate-600 ring-slate-200";
}

function StatusPill({ children }) {
  return <span className={`inline-flex items-center whitespace-nowrap rounded-full px-2.5 py-1 text-[11px] font-semibold ring-1 ring-inset ${statusStyle(children)}`}>{children}</span>;
}

